// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner, address actor) public {
        vm.assume(newOwner != address(0));
        vm.prank(address(0));
        c.transferOwnership(newOwner);
        vm.prank(actor);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok == (actor == newOwner), "owned() must succeed only for the owner");
    }
}
